"use client";
import {useEffect,useRef,useState} from "react";
import {CalendarDays,Users,LayoutGrid,History,ArrowRight,ArrowUpRight,ArrowLeftRight,Check,ChevronLeft,ChevronRight,Clock3,Download,Upload,Plus,Printer,Save,ShieldCheck,Sparkles,X,Menu,LockKeyhole,Unlock,AlertCircle,CheckCircle2,Leaf,Trash2} from "lucide-react";
import {floors,targets,localDate,minute,hhmm,uid,shiftEnd,seedWorkspace,migrateWorkspace,newDay,generateTeams,validateDay,floorCount,floorAt,onBreak,eventTimes,recordTransfer,closeJP2,importStaff,dutyHistory,workspaceSchema,templateTeams} from "../lib/teams";
import {RulesPanel,FairnessPanel,OperationsPanel,SuggestionsPanel,ChangeLog} from "./planning-tools";
